require __DIR__.'/../includes/admin.php';$a=require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');}if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Invalid CSRF token');}$act=$_POST['action']??'';$id=(int)($_POST['id']??0);$note=trim((string)($_POST['note']??''));try{
if($act==='approve_payment'||$act==='reject_payment'){if(!in_array($a['role'],['super_admin','finance'],true)){http_response_code(403);exit('Finance permission required');}$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM topup_requests WHERE id=? FOR UPDATE');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['status']!=='pending')throw new RuntimeException('Request missing or already reviewed.');if($act==='approve_payment'){$u=$pdo->prepare('SELECT id FROM users WHERE id=? AND status="active" FOR UPDATE');$u->execute([$r['user_id']]);if(!$u->fetch())throw new RuntimeException('Player account is not active.');$ref='topup-'.$r['id'];$l=$pdo->prepare('INSERT INTO coin_ledger(user_id,delta,kind,reference,note,admin_id) VALUES(?,?,?,?,?,?)');$l->execute([$r['user_id'],$r['coins'],'topup',$ref,'Verified UPI top-up',$a['id']]);$c=$pdo->prepare('UPDATE users SET coins=coins+? WHERE id=?');$c->execute([$r['coins'],$r['user_id']]);$status='approved';}else{$status='rejected';}$q=$pdo->prepare('UPDATE topup_requests SET status=?,admin_note=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status="pending"');$q->execute([$status,$note?:null,$a['id'],$id]);$n=$pdo->prepare('INSERT INTO notifications(user_id,title,message) VALUES(?,?,?)');$n->execute([$r['user_id'],'Top-up '.$status,$status==='approved'?'Your payment was verified and coins were credited.':'Your top-up was rejected. '.($note?:'Please contact support.')]);audit($pdo,(int)$a['id'],$act,'topup',$id,['utr'=>$r['utr'],'coins'=>$r['coins'],'note'=>$note]);$pdo->commit();
}elseif($act==='create_tournament'){if(!in_array($a['role'],['super_admin','tournament'],true))throw new RuntimeException('Tournament permission required.');$title=trim($_POST['title']??'');$game=trim($_POST['game']??'');$mode=trim($_POST['mode']??'Squad');$date=str_replace('T',' ',$_POST['starts_at']??'');$entry=max(0,(int)($_POST['entry_coins']??0));$prize=max(0,(int)($_POST['prize_coins']??0));$max=max(2,min(10000,(int)($_POST['max_teams']??64)));$status=in_array($_POST['status']??'upcoming',['draft','upcoming','live'],true)?$_POST['status']:'draft';if(!$title||!$game||!preg_match('/^\d{4}-\d\d-\d\d \d\d:\d\d$/',$date))throw new RuntimeException('Please complete tournament details.');$q=$pdo->prepare('INSERT INTO tournaments(title,game,mode,description,entry_coins,prize_coins,max_teams,starts_at,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$title,$game,$mode,trim($_POST['description']??''),$entry,$prize,$max,$date,$status,$a['id']]);audit($pdo,(int)$a['id'],'create_tournament','tournament',(int)$pdo->lastInsertId(),['title'=>$title]);
}elseif($act==='tournament_status'){if(!in_array($a['role'],['super_admin','tournament'],true))throw new RuntimeException('Tournament permission required.');$status=$_POST['status']??'';if(!in_array($status,['draft','upcoming','live','completed','cancelled'],true))throw new RuntimeException('Invalid status.');$q=$pdo->prepare('UPDATE tournaments SET status=? WHERE id=?');$q->execute([$status,$id]);audit($pdo,(int)$a['id'],'tournament_status','tournament',$id,['status'=>$status]);
}elseif($act==='settings_save'){if($a['role']!=='super_admin')throw new RuntimeException('Super admin permission required.');$allowed=['app_name','support_email','upi_id','coins_per_rupee','registration_enabled','maintenance_mode','home_notice','referral_coins','min_topup_rupees'];$values=[];foreach($allowed as $key){$v=trim((string)($_POST[$key]??''));if(in_array($key,['coins_per_rupee','referral_coins','min_topup_rupees'],true)){if(!ctype_digit($v))throw new RuntimeException('Numeric setting invalid: '.$key);$v=(string)max(0,(int)$v);}if(in_array($key,['registration_enabled','maintenance_mode'],true))$v=isset($_POST[$key])?'1':'0';if($key==='app_name' && ($v===''||strlen($v)>80))throw new RuntimeException('App name is required (max 80 chars).');if($key==='upi_id' && strlen($v)>120)throw new RuntimeException('UPI ID too long.');if($key==='support_email' && $v!==''&&!filter_var($v,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Support email is invalid.');$values[$key]=$v;}foreach($values as $key=>$v){$q=$pdo->prepare('INSERT INTO app_settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by),updated_at=NOW()');$q->execute([$key,$v,$a['id']]);}audit($pdo,(int)$a['id'],'settings_save','settings',null,$values);header('Location: index.php?tab=settings&saved=1');exit;
