}else throw new RuntimeException('Unknown action.');header('Location: index.php?tab='.($act==='approve_payment'||$act==='reject_payment'?'payments':($act==='player_status'?'players':'tournaments')));exit;
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(400);echo 'Action failed: '.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').' <a href="index.php">Back</a>';}
